import 'dart:convert';
import 'dart:io';
import 'dart:math';
import 'package:crypto/crypto.dart';
import 'package:dart_jsonwebtoken/dart_jsonwebtoken.dart';
import 'package:shelf/shelf.dart';
import 'package:shelf_router/shelf_router.dart';
import 'package:sqlite3/sqlite3.dart';
import 'package:uuid/uuid.dart';

class SaqiaServer {
  final Database db;
  final String jwtSecret;
  SaqiaServer(this.db, {required this.jwtSecret});

  Router router() {
    final r = Router();
    // وقت الخادم لمزامنة «مصدر الوقت = الخادم» في التطبيق (مسار عام بلا مصادقة).
    r.get('/api/v1/time', (Request req) => Response.ok(jsonEncode({'now': DateTime.now().toUtc().toIso8601String()}), headers: {'Content-Type': 'application/json'}));
    r.post('/api/v1/auth/login', _adminLogin);
    r.get('/api/v1/dashboard', _auth(_dashboard, roles: {'manager','accountant','operations'}));
    r.get('/api/v1/settings', _auth(_settings, roles: {'manager','accountant'}));
    r.put('/api/v1/settings', _auth(_settingsPut, roles: {'manager'}));
    r.get('/api/v1/beneficiaries', _auth(_beneficiaries, roles: {'manager','accountant','operations'}));
    r.post('/api/v1/beneficiaries', _auth(_beneficiaryCreate, roles: {'manager','accountant'}));
    r.get('/api/v1/beneficiaries/<id>', _auth(_beneficiary, roles: {'manager','accountant','operations'}));
    r.put('/api/v1/beneficiaries/<id>', _auth(_beneficiaryUpdate, roles: {'manager','accountant'}));
    r.delete('/api/v1/beneficiaries/<id>', _auth(_beneficiaryDelete, roles: {'manager','accountant'}));
    r.get('/api/v1/beneficiaries/<id>/statement', _auth(_beneficiaryStatement, roles: {'manager','accountant','operations'}));
    r.post('/api/v1/irrigations', _auth(_irrigationCreate, roles: {'manager','accountant'}));
    r.get('/api/v1/irrigations', _auth(_irrigations, roles: {'manager','accountant','operations'}));
    r.post('/api/v1/irrigations/<id>/cancel', _auth(_irrigationCancel, roles: {'manager','accountant'}));
    r.get('/api/v1/sessions', _auth(_sessions, roles: {'manager','accountant','operations'}));
    r.post('/api/v1/sessions/start', _auth(_sessionStart, roles: {'manager','accountant','operations'}));
    r.post('/api/v1/sessions/<id>/finish', _auth(_sessionFinish, roles: {'manager','accountant','operations'}));
    r.post('/api/v1/sessions/<id>/postpone', _auth(_sessionPostpone, roles: {'manager','accountant','operations'}));
    r.get('/api/v1/queue', _auth(_queue, roles: {'manager','accountant','operations'}));
    r.post('/api/v1/queue', _auth(_queueAdd, roles: {'manager','accountant','operations'}));
    r.post('/api/v1/queue/<id>/postpone', _auth(_queuePostpone, roles: {'manager','accountant','operations'}));
    r.post('/api/v1/queue/<id>/skip', _auth(_queueSkip, roles: {'manager'}));
    r.get('/api/v1/bookings', _auth(_bookings, roles: {'manager','accountant','operations'}));
    r.post('/api/v1/bookings/<id>/schedule', _auth(_bookingSchedule, roles: {'manager','accountant'}));
    r.post('/api/v1/bookings/<id>/cancel', _auth(_bookingCancel, roles: {'manager','accountant'}));
    r.get('/api/v1/payments', _auth(_payments, roles: {'manager','accountant'}));
    r.post('/api/v1/payments', _auth(_paymentCreate, roles: {'manager','accountant'}));
    r.get('/api/v1/cashboxes', _auth(_cashboxes, roles: {'manager','accountant'}));
    r.post('/api/v1/cashbox-transfers', _auth(_cashboxTransfer, roles: {'manager','accountant'}));
    r.get('/api/v1/diesel', _auth(_diesel, roles: {'manager','accountant','operations'}));
    r.post('/api/v1/diesel/movements', _auth(_dieselMovement, roles: {'manager','accountant'}));
    r.get('/api/v1/expenses', _auth(_expenses, roles: {'manager','accountant'}));
    r.post('/api/v1/expenses', _auth(_expenseCreate, roles: {'manager','accountant'}));
    r.get('/api/v1/workers', _auth(_workers, roles: {'manager','accountant'}));
    r.post('/api/v1/workers', _auth(_workerCreate, roles: {'manager','accountant'}));
    r.post('/api/v1/workers/<id>/transactions', _auth(_workerTransaction, roles: {'manager','accountant'}));
    r.get('/api/v1/partners', _auth(_partners, roles: {'manager','accountant'}));
    r.post('/api/v1/partners', _auth(_partnerCreate, roles: {'manager','accountant'}));
    r.post('/api/v1/partners/<id>/transactions', _auth(_partnerTransaction, roles: {'manager','accountant'}));
    r.get('/api/v1/accounting/journal', _auth(_journalReport, roles: {'manager','accountant'}));
    r.get('/api/v1/accounting/ledger', _auth(_ledger, roles: {'manager','accountant'}));
    r.get('/api/v1/reports/<name>', _auth(_reports, roles: {'manager','accountant'}));
    r.post('/api/v1/backup', _auth(_backup, roles: {'manager'}));
    r.post('/api/v1/restore', _auth(_restore, roles: {'manager'}));
    r.post('/api/v1/beneficiary/request-code', _beneficiaryRequestCode);
    r.post('/api/v1/beneficiary/session', _beneficiaryLogin);
    r.get('/api/v1/beneficiary/me', _beneficiaryAuth(_beneficiaryMe));
    r.get('/api/v1/beneficiary/requests', _beneficiaryAuth(_beneficiaryRequests));
    r.post('/api/v1/beneficiary/requests', _beneficiaryAuth(_beneficiaryRequestCreate));
    r.post('/api/v1/beneficiary/requests/<id>/cancel', _beneficiaryAuth(_beneficiaryRequestCancel));
    r.get('/api/v1/beneficiary/account', _beneficiaryAuth(_beneficiaryAccount));
    r.get('/api/v1/beneficiary/notifications', _beneficiaryAuth(_beneficiaryNotifications));
    r.post('/api/v1/beneficiary/notifications/<id>/read', _beneficiaryAuth(_beneficiaryNotificationRead));
    return r;
  }

  List<Map<String,Object?>> _rows(ResultSet rows) => rows.map((row) => {
    for (var i = 0; i < rows.columnNames.length; i++) rows.columnNames[i]: row[i]
  }).toList();
  Response _json(Object body, {int status = 200}) => Response(status, body: jsonEncode(body), headers: {'content-type':'application/json; charset=utf-8'});
  Future<Map<String,dynamic>> _body(Request r) async { try { final raw = await r.readAsString(); if (raw.trim().isEmpty) return {}; return jsonDecode(raw) as Map<String,dynamic>; } catch (_) { return {}; } }
  String _hash(String v) => sha256.convert(utf8.encode(v)).toString();
  String _token(Map<String,dynamic> claims) => JWT(claims).sign(SecretKey(jwtSecret), expiresIn: const Duration(hours: 12));
  Map<String,dynamic>? _verify(Request r) { final h=r.headers['authorization']??''; if(!h.startsWith('Bearer ')) return null; try { return JWT.verify(h.substring(7),SecretKey(jwtSecret)).payload as Map<String,dynamic>; } catch (_) { return null; } }
  Handler _auth(Handler Function(Request,Map<String,dynamic>) fn,{Set<String> roles=const{}})=>(Request r) async { final c=_verify(r); if(c==null)return _json({'error':'جلسة غير صالحة'},status:401); if(roles.isNotEmpty&&!roles.contains('${c['role']}'))return _json({'error':'لا تملك صلاحية تنفيذ العملية'},status:403); return fn(r,c); };
  Handler _beneficiaryAuth(Handler Function(Request,Map<String,dynamic>) fn)=>(Request r) async { final c=_verify(r); if(c==null||c['kind']!='beneficiary')return _json({'error':'جلسة المستفيد غير صالحة'},status:401); final exp=db.select('SELECT id FROM beneficiary_sessions WHERE beneficiary_id=? AND token_hash=? AND revoked_at IS NULL AND expires_at>? LIMIT 1',[c['beneficiaryId'],c['session'],DateTime.now().toIso8601String()]); if(exp.isEmpty)return _json({'error':'جلسة المستفيد منتهية'},status:401); return fn(r,c); };

  void _journal({required String description, required String referenceType, int? referenceId, required List<Map<String,Object?>> lines, int? userId}) {
    final debit=lines.fold<int>(0,(s,x)=>s+((x['debit'] as num?)?.round()??0));
    final credit=lines.fold<int>(0,(s,x)=>s+((x['credit'] as num?)?.round()??0));
    if(debit<=0 || debit!=credit) throw StateError('القيد غير متوازن');
    final now=DateTime.now().toIso8601String();
    db.execute('INSERT INTO journal_entries(date,reference_type,reference_id,description,status,created_by,created_at) VALUES(?,?,?,?,?,?,?)',[now,referenceType,referenceId,description,'posted',userId,now]);
    final id=db.lastInsertRowId;
    for(final line in lines){db.execute('INSERT INTO journal_lines(journal_entry_id,account_id,beneficiary_id,worker_id,partner_id,debit,credit,memo) VALUES(?,?,?,?,?,?,?,?)',[id,line['account_id'],line['beneficiary_id'],line['worker_id'],line['partner_id'],line['debit'],line['credit'],line['memo']]);}
  }
  Future<Response> _atomic(Future<Response> Function() work) async {
    db.execute('BEGIN IMMEDIATE');
    try { final response=await work(); if(response.statusCode>=400){db.execute('ROLLBACK');}else{db.execute('COMMIT');} return response; }
    catch(e){try{db.execute('ROLLBACK');}catch(_){} return _json({'error':'فشلت العملية الذرية: $e'},status:422);}
  }
  int _accountId(String code){final r=db.select('SELECT id FROM accounts WHERE code=? LIMIT 1',[code]);if(r.isEmpty)throw StateError('الحساب غير موجود: $code');return r.first['id'] as int;}
  int _stationId(Map<String,dynamic> c)=>(c['stationId'] as num?)?.toInt()??1;
  bool _owns(String table,int id,int stationId){final r=db.select('SELECT id FROM $table WHERE id=? AND station_id=? LIMIT 1',[id,stationId]);return r.isNotEmpty;}
  void _requireOwn(String table,int? id,int stationId,String label){if(id==null||!_owns(table,id,stationId))throw StateError('$label لا يتبع المحطة الحالية');}
  void _audit(int userId,String operation,String table,int? recordId,{String? reason}){db.execute('INSERT INTO audit_logs(user_id,operation,table_name,record_id,reason,created_at) VALUES(?,?,?,?,?,?)',[userId,operation,table,recordId,reason,DateTime.now().toIso8601String()]);}
  int _round(double v,String mode)=>mode=='up'?v.ceil():mode=='down'?v.floor():v.round();

  Future<Response> _adminLogin(Request r) async { final b=await _body(r); final u='${b['username']??''}'; final p=_hash('${b['password']??''}'); final rows=db.select('SELECT id,station_id,name,role FROM app_users WHERE username=? AND password_hash=? AND active=1',[u,p]); if(rows.isEmpty)return _json({'error':'اسم المستخدم أو كلمة المرور غير صحيحة'},status:401); final x=_rows(rows).first; return _json({'token':_token({'kind':'admin','userId':x['id'],'stationId':x['station_id'],'role':x['role']}),'user':{'id':x['id'],'name':x['name'],'role':x['role']}}); }
  Future<Response> _dashboard(Request r,Map<String,dynamic> c) async { final x=_rows(db.select("SELECT (SELECT COUNT(*) FROM beneficiaries WHERE status='active') beneficiaries,(SELECT COUNT(*) FROM queue_entries WHERE status IN ('waiting','postponed')) queue,(SELECT COUNT(*) FROM booking_requests WHERE status IN ('new','under_review')) bookings,(SELECT COUNT(*) FROM irrigation_sessions WHERE status='running') running_sessions,(SELECT COALESCE(SUM(total_amount),0) FROM irrigations WHERE status!='cancelled') revenue,(SELECT COALESCE(SUM(amount),0) FROM payments WHERE status='posted') paid,(SELECT COALESCE(SUM(amount),0) FROM expenses WHERE status='posted') expenses")).first; return _json(x); }
  Future<Response> _settings(Request r,Map<String,dynamic> c) async => _json({for(final x in db.select('SELECT key,value FROM settings')) x['key'] as String:x['value']});
  Future<Response> _settingsPut(Request r,Map<String,dynamic> c) async { final b=await _body(r); for(final e in b.entries){db.execute('INSERT OR REPLACE INTO settings(key,value,updated_at) VALUES(?,?,?)',[e.key,'${e.value}',DateTime.now().toIso8601String()]);} return _settings(r,c); }
  Future<Response> _beneficiaries(Request r,Map<String,dynamic> c) async => _json(_rows(db.select("SELECT * FROM beneficiaries WHERE status='active' AND station_id=? ORDER BY name",[_stationId(c)])));
  Future<Response> _beneficiaryCreate(Request r,Map<String,dynamic> c) async { final b=await _body(r); if('${b['name']??''}'.trim().isEmpty)return _json({'error':'اسم المستفيد مطلوب'},status:422); final now=DateTime.now().toIso8601String(); final id=db.lastInsertRowId; db.execute('INSERT INTO beneficiaries(station_id,name,phone,address,location,jerba_number,area,is_needy,opening_balance,carried_balance,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,\'active\',?,?)',[_stationId(c),b['name'],b['phone'],b['address'],b['location'],b['jerba_number'],b['area'],b['is_needy']==true?1:0,(b['opening_balance'] as num?)?.round()??0,(b['carried_balance'] as num?)?.round()??0,now,now]); return _json({'id':db.lastInsertRowId}); }
  Future<Response> _beneficiary(Request r,Map<String,dynamic> c) async { final id=int.parse(r.params['id']!); final rows=db.select('SELECT * FROM beneficiaries WHERE id=? AND station_id=?',[id,_stationId(c)]); return rows.isEmpty?_json({'error':'المستفيد غير موجود'},status:404):_json(_rows(rows).first); }
  Future<Response> _beneficiaryUpdate(Request r,Map<String,dynamic> c) async { final id=int.parse(r.params['id']!); final b=await _body(r); const allowed=['name','phone','address','location','jerba_number','area','is_needy','notes']; final sets=<String>[];final args=<Object?>[];for(final k in allowed){if(b.containsKey(k)){sets.add('$k=?');args.add(b[k] is bool?(b[k]?1:0):b[k]);}}if(sets.isEmpty)return _json({'error':'لا توجد حقول قابلة للتعديل'},status:422);args.add(DateTime.now().toIso8601String());args.add(id);args.add(_stationId(c)); db.execute('UPDATE beneficiaries SET ${sets.join(',')},updated_at=? WHERE id=? AND station_id=?',args);return _beneficiary(r,c); }
  Future<Response> _beneficiaryDelete(Request r,Map<String,dynamic> c) async { final id=int.parse(r.params['id']!); final b=await _body(r); if('${b['reason']??''}'.trim().isEmpty)return _json({'error':'سبب الحذف المنطقي مطلوب'},status:422); db.execute("UPDATE beneficiaries SET status='deleted',updated_at=? WHERE id=? AND station_id=?",[DateTime.now().toIso8601String(),id,_stationId(c)]); return _json({'ok':true}); }
  Future<Response> _beneficiaryStatement(Request r,Map<String,dynamic> c) async { final id=int.parse(r.params['id']!); return _json(_rows(db.select('SELECT * FROM irrigations WHERE beneficiary_id=? AND status!=\'cancelled\' ORDER BY start_datetime DESC',[id]))); }

  int _minutes(DateTime start,DateTime end,bool midnight){var e=end;if(!e.isAfter(start)){if(!midnight)throw StateError('وقت النهاية يجب أن يكون بعد وقت البداية');e=e.add(const Duration(days:1));}final m=e.difference(start).inMinutes;if(m<=0)throw StateError('مدة السقي غير صالحة');return m;}
  Future<Response> _irrigationCreateUnsafe(Request r,Map<String,dynamic> c) async { final b=await _body(r); try { _requireOwn('beneficiaries',(b['beneficiary_id'] as num?)?.toInt(),_stationId(c),'المستفيد'); _requireOwn('pumps',(b['pump_id'] as num?)?.toInt()??1,_stationId(c),'المضخة'); final start=DateTime.parse('${b['start']}');final end=DateTime.parse('${b['end']}');final settings={for(final x in db.select('SELECT key,value FROM settings'))x['key'] as String:x['value']};final system='${b['system_type']??settings['system_type']??'diesel'}';final mins=_minutes(start,end,settings['allow_midnight_crossing']=='true');final cloud=(b['cloud_minutes'] as num?)?.round()??0;final charge=system=='solar'?((mins-cloud).clamp(0,mins)):mins;final waterRate=system=='diesel'?(int.tryParse(settings['diesel_hourly_water_rate']??'0')??0):system=='solar'?(int.tryParse(settings['solar_hourly_rate']??'0')??0):(int.tryParse(settings['third_type_hourly_rate']??'0')??0);final water=_round(charge/60*waterRate,settings['rounding']??'nearest');final liters=system=='diesel'?charge/60*(double.tryParse(settings['diesel_liters_per_hour']??'0')??0):0;final fuel=_round(liters*(int.tryParse(settings['diesel_price_per_liter']??'0')??0),settings['rounding']??'nearest');final total=water+fuel;final paid=(b['paid_amount'] as num?)?.round()??0;if(paid<0||paid>total)throw StateError('المدفوع يجب أن يكون بين صفر وإجمالي السقاية');final now=DateTime.now().toIso8601String();db.execute('INSERT INTO irrigations(station_id,pump_id,beneficiary_id,date,start_datetime,end_datetime,minutes,system_type,water_hourly_rate_snapshot,diesel_liters_per_hour_snapshot,diesel_price_snapshot,solar_hourly_rate_snapshot,third_type_hourly_rate_snapshot,cloud_minutes,chargeable_minutes,water_amount,diesel_amount,total_amount,paid_amount,status,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[_stationId(c),b['pump_id']??1,b['beneficiary_id'],start.toIso8601String().substring(0,10),start.toIso8601String(),end.toIso8601String(),mins,system,int.tryParse(settings['diesel_hourly_water_rate']??'0')??0,double.tryParse(settings['diesel_liters_per_hour']??'0')??0,int.tryParse(settings['diesel_price_per_liter']??'0')??0,int.tryParse(settings['solar_hourly_rate']??'0')??0,int.tryParse(settings['third_type_hourly_rate']??'0')??0,cloud,charge,water,fuel,total,paid,'posted',c['userId'],now,now]);final irrigationId=db.lastInsertRowId;final rec=_accountId('1200'),waterRev=_accountId('4000'),fuelRev=_accountId('4010');final lines=<Map<String,Object?>>[{'account_id':rec,'beneficiary_id':b['beneficiary_id'],'debit':total,'credit':0,'memo':'استحقاق سقاية'}];if(water>0)lines.add({'account_id':waterRev,'debit':0,'credit':water,'memo':'إيراد الماء'});if(fuel>0)lines.add({'account_id':fuelRev,'debit':0,'credit':fuel,'memo':'قيمة الديزل'});_journal(description:'سقاية رقم $irrigationId',referenceType:'irrigation',referenceId:irrigationId,lines:lines,userId:c['userId']);if(system=='diesel'&&liters>0){final stock=(db.select("SELECT COALESCE(SUM(CASE WHEN kind IN ('receipt','opening_balance','correction') THEN liters WHEN kind IN ('delivery','consumption') THEN -liters ELSE 0 END),0) stock FROM diesel_movements").first['stock'] as num).toDouble();final shortage=liters-stock;if(shortage>0){final advanceAmount=(shortage*(int.tryParse(settings['diesel_price_per_liter']??'0')??0)).round();db.execute('INSERT INTO diesel_movements(beneficiary_id,irrigation_id,kind,liters,unit_price,amount,date,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?)',[b['beneficiary_id'],irrigationId,'advance',shortage,int.tryParse(settings['diesel_price_per_liter']??'0')??0,advanceAmount,now,'سلفة ديزل تلقائية',c['userId']]);final d=_accountId('1200'),cash=_accountId('1000');_journal(description:'سلفة ديزل تلقائية',referenceType:'diesel_advance',referenceId:db.lastInsertRowId,lines:[{'account_id':d,'beneficiary_id':b['beneficiary_id'],'debit':advanceAmount,'credit':0},{'account_id':cash,'debit':0,'credit':advanceAmount}],userId:c['userId']);}db.execute('INSERT INTO diesel_movements(beneficiary_id,irrigation_id,kind,liters,unit_price,amount,date,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?)',[b['beneficiary_id'],irrigationId,'consumption',liters,int.tryParse(settings['diesel_price_per_liter']??'0')??0,fuel,now,'استهلاك السقاية',c['userId']]);}
if(paid>0){final pm=(b['payment_method_id'] as num?)?.toInt()??1;final cb=(b['cashbox_id'] as num?)?.toInt()??1;_requireOwn('payment_methods',pm,_stationId(c),'طريقة الدفع');_requireOwn('cashboxes',cb,_stationId(c),'الصندوق');db.execute('INSERT INTO payments(beneficiary_id,amount,date,payment_method_id,cashbox_id,reference_number,notes,status,created_by) VALUES(?,?,?,?,?,?,?,?,?)',[b['beneficiary_id'],paid,now,pm,cb,b['reference_number'],b['payment_notes'],'posted',c['userId']]);final method=db.select('SELECT ledger_account_code,type FROM payment_methods WHERE id=?',[pm]).first;final cashCode='${method['ledger_account_code']??'1000'}';_journal(description:'دفعة مرتبطة بالسقاية',referenceType:'payment',referenceId:db.lastInsertRowId,lines:[{'account_id':_accountId(cashCode),'debit':paid,'credit':0},{'account_id':rec,'beneficiary_id':b['beneficiary_id'],'debit':0,'credit':paid}],userId:c['userId']);}
return _json({'id':irrigationId,'minutes':mins,'chargeable_minutes':charge,'total_amount':total,'paid_amount':paid});}catch(e){return _json({'error':'تعذر تسجيل السقاية: $e'},status:422);} }
  Future<Response> _irrigationCreate(Request r,Map<String,dynamic> c) => _atomic(() => _irrigationCreateUnsafe(r,c));
  Future<Response> _irrigations(Request r,Map<String,dynamic> c) async => _json(_rows(db.select('SELECT i.*,b.name beneficiary_name,p.name pump_name FROM irrigations i JOIN beneficiaries b ON b.id=i.beneficiary_id JOIN pumps p ON p.id=i.pump_id WHERE i.status!=\'cancelled\' ORDER BY i.start_datetime DESC LIMIT 1000')));
  Future<Response> _irrigationCancel(Request r,Map<String,dynamic> c) async {final id=int.parse(r.params['id']!);final b=await _body(r);if('${b['reason']??''}'.trim().isEmpty)return _json({'error':'سبب الإلغاء مطلوب'},status:422);db.execute("UPDATE irrigations SET status='cancelled',override_reason=? WHERE id=?",[b['reason'],id]);return _json({'ok':true});}

  Future<Response> _sessions(Request r,Map<String,dynamic> c) async => _json(_rows(db.select('SELECT s.*,b.name beneficiary_name,p.name pump_name FROM irrigation_sessions s JOIN beneficiaries b ON b.id=s.beneficiary_id JOIN pumps p ON p.id=s.pump_id ORDER BY COALESCE(s.actual_start,s.planned_start) DESC')));
  Future<Response> _sessionStart(Request r,Map<String,dynamic> c) async {final b=await _body(r);final pump=(b['pump_id'] as num?)?.toInt()??1;_requireOwn('pumps',pump,_stationId(c),'المضخة');_requireOwn('beneficiaries',(b['beneficiary_id'] as num?)?.toInt(),_stationId(c),'المستفيد');final active=db.select("SELECT id FROM irrigation_sessions WHERE pump_id=? AND status='running'",[pump]);if(active.isNotEmpty)return _json({'error':'المضخة لديها جلسة فعالة'},status:409);final now=DateTime.now().toIso8601String();db.execute("INSERT INTO irrigation_sessions(beneficiary_id,queue_entry_id,booking_id,pump_id,planned_start,actual_start,timer_started_at,status) VALUES(?,?,?,?,?,?,?,\'running\')",[b['beneficiary_id'],b['queue_id'],b['booking_id'],pump,now,now,now]);return _json({'id':db.lastInsertRowId,'started_at':now});}
  Future<Response> _sessionFinishUnsafe(Request r,Map<String,dynamic> c) async {
    final id=int.parse(r.params['id']!); final rows=db.select('SELECT s.*,p.station_id,p.system_type FROM irrigation_sessions s JOIN pumps p ON p.id=s.pump_id WHERE s.id=?',[id]);
    if(rows.isEmpty)return _json({'error':'الجلسة غير موجودة'},status:404); final s=rows.first; if(s['status']!='running')return _json({'error':'الجلسة ليست قيد التشغيل'},status:409);
    final end=DateTime.now(); final start=DateTime.parse(s['actual_start'] as String); final settings={for(final x in db.select('SELECT key,value FROM settings'))x['key'] as String:x['value']};
    final mins=_minutes(start,end,settings['allow_midnight_crossing']=='true'); final cloud=(await _body(r))['cloud_minutes']; final cloudMin=(cloud as num?)?.round()??0; final charge=s['system_type']=='solar'?(mins-cloudMin).clamp(0,mins):mins;
