  Future<Response> _reports(Request r,Map<String,dynamic> c) async {final name=r.params['name']!; final allowed={'cash_flow','time_comparison','monthly_financial','income','payment_methods','expenses','cashboxes','queue_bookings','payment_log','beneficiary_statement','beneficiary_detailed','beneficiary_stats','needy','diesel_inventory','activity_overview','oil_status','debts','beneficiary_list','revenue_comparison','system_comparison','journal','ledger','worker_transactions','partner_accounts'};if(!allowed.contains(name))return _json({'error':'التقرير غير معروف'},status:404);return _json({'report':name,'rows':_reportRows(name)});}
  List<Map<String,Object?>> _reportRows(String name){switch(name){case 'cash_flow':return _rows(db.select("SELECT date,'payment' kind,amount,'قبض' title FROM payments WHERE status='posted' UNION ALL SELECT date,'expense' kind,-amount,title FROM expenses WHERE status='posted' ORDER BY date DESC"));case 'income':return _rows(db.select("SELECT system_type,COUNT(*) operations,SUM(water_amount) water_income,SUM(diesel_amount) diesel_income,SUM(total_amount) total FROM irrigations WHERE status!='cancelled' GROUP BY system_type"));case 'system_comparison':return _rows(db.select("SELECT system_type,COUNT(*) operations,SUM(minutes) minutes,SUM(total_amount) total,SUM(diesel_amount) diesel_cost FROM irrigations WHERE status!='cancelled' GROUP BY system_type"));case 'journal':return _rows(db.select('SELECT * FROM journal_entries ORDER BY date DESC'));case 'ledger':return _rows(db.select('SELECT * FROM journal_lines ORDER BY id DESC'));default:return _rows(db.select('SELECT * FROM irrigations WHERE status!=\'cancelled\' ORDER BY start_datetime DESC LIMIT 1000'));}}
  Future<Response> _backup(Request r,Map<String,dynamic> c) async {final b=await _body(r);final path='${b['path']??'saqia_backup_${DateTime.now().millisecondsSinceEpoch}.db'}';try{db.execute('VACUUM INTO ?', [path]);return _json({'ok':true,'path':path});}catch(e){return _json({'error':'فشل النسخ الاحتياطي: $e'},status:500);}}
  Future<Response> _restore(Request r,Map<String,dynamic> c) async {
    final b=await _body(r); final encoded='${b['base64']??''}'; if(encoded.isEmpty)return _json({'error':'يجب إرسال ملف النسخة الاحتياطية بصيغة base64'},status:422);
    final bytes=base64Decode(encoded); if(bytes.length<16 || ascii.decode(bytes.take(15).toList(),allowInvalid:true)!='SQLite format 3')return _json({'error':'النسخة ليست SQLite صالحة'},status:422);
    final tmp='${Directory.systemTemp.path}/saqia_restore_${DateTime.now().millisecondsSinceEpoch}.db'; final f=File(tmp); await f.writeAsBytes(bytes,flush:true);
    try { final probe=sqlite3.open(tmp,mode:OpenMode.readOnly); final required=['stations','pumps','beneficiaries','irrigations','payments','cashboxes','journal_entries','journal_lines','settings']; for(final t in required){if(probe.select("SELECT name FROM sqlite_master WHERE type='table' AND name=?",[t]).isEmpty){probe.dispose();return _json({'error':'النسخة ناقصة: $t'},status:422);}} probe.dispose();
      final current=Platform.environment['SAQIA_DB']??'../saqia_station_v2.db'; final backup='$current.before_restore_${DateTime.now().millisecondsSinceEpoch}'; File(current).copySync(backup); File(tmp).copySync(current); return _json({'ok':true,'backup_before_restore':backup});
    } catch(e){return _json({'error':'فشل الاستعادة: $e'},status:500);} finally {try{await f.delete();}catch(_){}}
  }

  Future<Response> _beneficiaryRequestCode(Request r) async {final b=await _body(r);final phone='${b['phone']??''}';final rows=db.select("SELECT id FROM beneficiaries WHERE phone=? AND status='active'",[phone]);if(rows.isEmpty)return _json({'error':'رقم الهاتف غير مسجل'},status:404);final id=rows.first['id'] as int;final code=(100000+Random.secure().nextInt(900000)).toString();db.execute('INSERT INTO beneficiary_auth_codes(beneficiary_id,code_hash,expires_at,created_at) VALUES(?,?,?,?)',[id,_hash(code),DateTime.now().add(const Duration(minutes:10)).toIso8601String(),DateTime.now().toIso8601String()]);final out=<String,Object?>{'ok':true,'message':'تم إنشاء رمز آمن صالح لمدة 10 دقائق'};if(Platform.environment['SAQIA_DEV_OTP']=='true')out['dev_code']=code;return _json(out);}
  Future<Response> _beneficiaryLogin(Request r) async {final b=await _body(r);final phone='${b['phone']??''}';final code='${b['code']??''}';final rows=db.select("SELECT id FROM beneficiaries WHERE phone=? AND status='active'",[phone]);if(rows.isEmpty)return _json({'error':'رقم الهاتف غير مسجل'},status:401);final id=rows.first['id'] as int;final expected=db.select('SELECT id,code_hash,attempts FROM beneficiary_auth_codes WHERE beneficiary_id=? AND used_at IS NULL AND expires_at>? ORDER BY id DESC LIMIT 1',[id,DateTime.now().toIso8601String()]);if(expected.isEmpty)return _json({'error':'الرمز غير صحيح أو منتهي'},status:401);
    final attempts=(expected.first['attempts'] as int?)??0; if(attempts>=5)return _json({'error':'تم تجاوز عدد محاولات الرمز'},status:429);
    if(expected.first['code_hash']!=_hash(code)){db.execute('UPDATE beneficiary_auth_codes SET attempts=attempts+1 WHERE id=?',[expected.first['id']]);return _json({'error':'الرمز غير صحيح أو منتهي'},status:401);}db.execute('UPDATE beneficiary_auth_codes SET used_at=? WHERE id=?',[DateTime.now().toIso8601String(),expected.first['id']]);final session=const Uuid().v4();db.execute('INSERT INTO beneficiary_sessions(beneficiary_id,token_hash,expires_at,created_at) VALUES(?,?,?,?)',[id,_hash(session),DateTime.now().add(const Duration(hours:12)).toIso8601String(),DateTime.now().toIso8601String()]);return _json({'token':_token({'kind':'beneficiary','beneficiaryId':id,'session':_hash(session)})});}
  int _bid(Map<String,dynamic> c)=>c['beneficiaryId'] as int;
  Future<Response> _beneficiaryMe(Request r,Map<String,dynamic> c) async {final rows=db.select('SELECT id,name,phone,address,location,jerba_number,area FROM beneficiaries WHERE id=?',[_bid(c)]);return rows.isEmpty?_json({'error':'المستفيد غير موجود'},status:404):_json(_rows(rows).first);}
  Future<Response> _beneficiaryRequests(Request r,Map<String,dynamic> c) async => _json(_rows(db.select('SELECT * FROM booking_requests WHERE beneficiary_id=? ORDER BY created_at DESC',[_bid(c)])));
  Future<Response> _beneficiaryRequestCreate(Request r,Map<String,dynamic> c) async {final b=await _body(r);final now=DateTime.now().toIso8601String();db.execute("INSERT INTO booking_requests(beneficiary_id,created_at,status,notes) VALUES(?,?,\'new\',?)",[_bid(c),now,b['notes']]);return _json({'id':db.lastInsertRowId});}
  Future<Response> _beneficiaryRequestCancel(Request r,Map<String,dynamic> c) async {final id=int.parse(r.params['id']!);final b=await _body(r);db.execute("UPDATE booking_requests SET status='cancelled',cancel_reason=? WHERE id=? AND beneficiary_id=? AND status IN ('new','under_review')",['${b['reason']??''}',id,_bid(c)]);return _json({'ok':true});}
  Future<Response> _beneficiaryAccount(Request r,Map<String,dynamic> c) async {
    final id=_bid(c);
    final settings={for(final x in db.select('SELECT key,value FROM settings'))x['key'] as String:x['value']};
    final includeDiesel=settings['diesel_delivery_financial_credit']=='true';
    final x=_rows(db.select('''SELECT b.opening_balance,b.carried_balance,
      COALESCE((SELECT SUM(total_amount) FROM irrigations WHERE beneficiary_id=b.id AND status!='cancelled'),0) due,
      COALESCE((SELECT SUM(amount) FROM diesel_movements WHERE beneficiary_id=b.id AND kind='advance' AND irrigation_id IS NULL),0) advances,
      COALESCE((SELECT SUM(amount) FROM payments WHERE beneficiary_id=b.id AND status='posted'),0) paid,
      COALESCE((SELECT SUM(amount) FROM diesel_movements WHERE beneficiary_id=b.id AND kind='delivery'),0) diesel_credit
      FROM beneficiaries b WHERE b.id=?''',[id])).first;
    final balance=(x['opening_balance'] as num)+(x['carried_balance'] as num)+(x['due'] as num)+(x['advances'] as num)-(x['paid'] as num)-(includeDiesel?(x['diesel_credit'] as num):0);
    return _json({...x,'balance':balance,'label':balance>0?'عليه $balance ريال':balance<0?'له ${-balance} ريال':'متوازن'});
  }
  Future<Response> _beneficiaryNotifications(Request r,Map<String,dynamic> c) async => _json(_rows(db.select('SELECT * FROM notifications WHERE beneficiary_id=? ORDER BY created_at DESC',[_bid(c)])));
  Future<Response> _beneficiaryNotificationRead(Request r,Map<String,dynamic> c) async {final id=int.parse(r.params['id']!);db.execute('UPDATE notifications SET read_at=? WHERE id=? AND beneficiary_id=?',[DateTime.now().toIso8601String(),id,_bid(c)]);return _json({'ok':true});}
